function toggleExpandRow(receiveNo) {
    if (gExpandedRows.has(receiveNo)) gExpandedRows.delete(receiveNo);
    else gExpandedRows.add(receiveNo);
    renderTable();
}

function renderNestedIssueTable(receiveNo) {
    const docIssues = gIssues.filter(i => i.doc_receive_no === receiveNo);

    if (docIssues.length === 0) {
        return `<div style="text-align:center;padding:28px 0;color:#94a3b8;">
            <i class="fa-solid fa-inbox" style="font-size:32px;margin-bottom:10px;display:block;opacity:0.4;"></i>
            尚無醫師函詢項目，點選「新增函詢」即可建立。
        </div>`;
    }

    let rowsHtml = "";
    docIssues.forEach(issue => {
        let statusSelectClass = "status-sent";
        if (issue.status === "待發送")   statusSelectClass = "status-pending";
        else if (issue.status === "已發送")   statusSelectClass = "status-sent";
        else if (issue.status === "待回覆")   statusSelectClass = "status-sent";
        else if (issue.status === "已回覆")   statusSelectClass = "status-replied";
        else if (issue.status === "退回補件") statusSelectClass = "status-returned";
        else if (issue.status === "已完成")   statusSelectClass = "status-completed";

        const isOverdue = isIssueOverdue(issue);
        const overdueBadge = isOverdue ? `<span class="badge badge-danger" style="margin-top:4px;"><i class="fa-solid fa-clock"></i> 逾期</span>` : "";

        const statusSelectHtml = `
            <select class="issue-status-select ${statusSelectClass}"
                    onchange="handleDirectIssueStatusChange('${escapeHtml(issue.issue_id)}', this.value)"
                    title="點擊直接修改狀態">
                <option value="待發送"  ${issue.status === "待發送"  ? "selected" : ""}>⏳ 待發送</option>
                <option value="已發送"  ${issue.status === "已發送"  ? "selected" : ""}>✉️ 已發送</option>
                <option value="待回覆"  ${issue.status === "待回覆"  ? "selected" : ""}>📨 待回覆</option>
                <option value="已回覆"  ${issue.status === "已回覆"  ? "selected" : ""}>📥 已回覆</option>
                <option value="退回補件" ${issue.status === "退回補件" ? "selected" : ""}>↩️ 退回補件</option>
                <option value="已完成"  ${issue.status === "已完成"  ? "selected" : ""}>✅ 已完成</option>
            </select>
        `;

        rowsHtml += `
            <tr>
                <td style="min-width:150px;">
                    <div class="dr-name-cell">
                        <span class="dr-name"><i class="fa-solid fa-user-doctor" style="color:#0f766e;margin-right:5px;font-size:12px;"></i>${escapeHtml(issue.doctor_name)}</span>
                        <span class="dr-email"><i class="fa-solid fa-envelope" style="font-size:10px;"></i>${escapeHtml(issue.doctor_email)}</span>
                    </div>
                </td>
                <td style="min-width:260px;">
                    <div class="multiline-box question-box">${formatMultilineHtml(issue.question)}</div>
                </td>
                <td style="min-width:220px;">
                    ${issue.doctor_reply
                        ? `<div class="multiline-box reply-box">${formatMultilineHtml(issue.doctor_reply)}</div>`
                        : `<div style="color:#94a3b8;text-align:center;padding:12px 0;"><i class="fa-regular fa-clock" style="display:block;font-size:20px;margin-bottom:4px;"></i>尚無回覆</div>`}
                </td>
                <td style="min-width:150px;">
                    ${statusSelectHtml}
                    ${overdueBadge}
                </td>
                <td style="min-width:100px;font-size:12.5px;color:#64748b;">${escapeHtml(issue.sent_at || '-')}</td>
                <td style="min-width:100px;font-size:12.5px;color:#64748b;">${escapeHtml(issue.replied_at || '-')}</td>
                <td style="min-width:130px;">
                    <div class="action-btn-group">
                        <div class="btn-row">
                            <button class="btn btn-sm btn-primary" onclick="previewEmailModal('${escapeHtml(issue.issue_id)}', 1)" title="發送函詢信">
                                <i class="fa-solid fa-paper-plane"></i> 寄信
                            </button>
                            <button class="btn btn-sm btn-outline-secondary" onclick="openIssueModalForEdit('${escapeHtml(issue.issue_id)}')" title="編輯">
                                <i class="fa-solid fa-pen"></i> 編輯
                            </button>
                            <button class="btn btn-sm btn-outline-danger" onclick="deleteIssue('${escapeHtml(issue.issue_id)}')" title="刪除">
                                <i class="fa-solid fa-trash"></i>
                            </button>
                        </div>
                        <div class="btn-row">
                            <button class="btn btn-sm btn-outline-success" onclick="completeIssue('${escapeHtml(issue.issue_id)}')" title="結案">
                                <i class="fa-solid fa-check"></i> 結案
                            </button>
                            <button class="btn btn-sm btn-outline-info" onclick="openSimulateReplyModal('${escapeHtml(issue.issue_id)}')" title="模擬回信">
                                <i class="fa-solid fa-reply"></i> 模擬
                            </button>
                            <button class="btn btn-sm btn-outline-secondary" onclick="openReturnReasonModal('${escapeHtml(issue.issue_id)}')" title="退回補件">
                                <i class="fa-solid fa-rotate-left"></i> 退回
                            </button>
                        </div>
                    </div>
                </td>
            </tr>
        `;
    });

    return `
        <table class="nested-table">
            <thead>
                <tr>
                    <th>醫師姓名</th>
                    <th>函詢問題內容</th>
                    <th>醫師意見回覆</th>
                    <th>狀態</th>
                    <th>寄件時間</th>
                    <th>回覆時間</th>
                    <th>操作</th>
                </tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
        </table>
    `;
}

function handleDirectIssueStatusChange(issueId, newStatus) {
    const issue = gIssues.find(i => i.issue_id === issueId);
    if (!issue) return;

    if (newStatus === "退回補件") {
        openReturnReasonModal(issueId);
        return;
    }

    if (newStatus === "已完成") {
        completeIssue(issueId);
        return;
    }

    issue.status = newStatus;
    const nowStr = new Date().toISOString().replace("T", " ").substring(0, 16);
    if (newStatus === "已發送" && !issue.sent_at) {
        issue.sent_at = nowStr;
    } else if (newStatus === "已回覆" && !issue.replied_at) {
        issue.replied_at = nowStr;
    }

    // 重新評估公文主檔狀態
    const docIssues = gIssues.filter(i => i.doc_receive_no === issue.doc_receive_no);
    const mainDoc = gMainDocs.find(d => d.doc_receive_no === issue.doc_receive_no);
    if (mainDoc) {
        if (docIssues.length > 0 && docIssues.every(i => i.status === "已完成")) {
            mainDoc.doc_status = "已完成";
        } else {
            mainDoc.doc_status = "處理中";
        }
    }

    saveDataToStorage();
    renderDashboard();
    renderTable();
    showToast(`已成功將醫師函詢狀態變更為「${newStatus}」`, "success");
}

