function saveSettings() {
    const gasUrl = document.getElementById("cfg_gas_url") ? document.getElementById("cfg_gas_url").value.trim() : "";
    if (gasUrl) localStorage.setItem("GAS_WEBHOOK_URL", gasUrl);
    showToast("系統與 Google 設定已儲存", "success");
    closeModal("modalSettings");
}

function openModal(id) {
    if (id === "modalSettings") {
        if (document.getElementById("cfg_gas_url")) {
            document.getElementById("cfg_gas_url").value = getGasWebhookUrl();
        }
    }
    document.getElementById(id).classList.add("active");
}

function closeModal(id) {
    document.getElementById(id).classList.remove("active");
}

function showToast(message, type = "info") {
    const toast = document.getElementById("toastNotification");
    toast.textContent = message;
    toast.className = `toast toast-${type}`;
    toast.classList.remove("hidden");

    setTimeout(() => {
        toast.classList.add("hidden");
    }, 3500);
}


function formatMultilineHtml(text) {
    if (!text) return "";
    let raw = String(text).replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();
    if (!raw) return "";

    // Separate sub-questions onto clean lines
    raw = raw.replace(/([^\n])\s*(\([一二三四五六七八九十]+\)|\([0-9]+\)|[0-9]+[.-][0-9]*[.)]?|[0-9]+\.)/g, '$1\n$2');
    raw = raw.replace(/([^\n])\s*(因案件有時效性|請惠示醫理見解|請於.*?前回覆|備註：|病人：|案由主旨：)/g, '$1\n$2');

    const lines = raw.split("\n").map(l => l.replace(/^[\s\u3000\t]+/, "").trim()).filter(l => l.length > 0);

    let html = "";
    lines.forEach((line) => {
        const bulletMatch = line.match(/^(\([一二三四五六七八九十]+\)|\([0-9]+\)|[0-9]+[.-][0-9]*[.)]?|[0-9]+\.)\s*(.*)/);
        if (bulletMatch) {
            const num = escapeHtml(bulletMatch[1]);
            const rest = escapeHtml(bulletMatch[2] || "");
            html += `<div class="qa-line"><strong class="qa-num">${num}</strong> ${rest}</div>`;
        } else if (line.includes("請惠示醫理見解") || line.includes("請於") || line.includes("備註：")) {
            html += `<div class="qa-line qa-sub-notice"><i class="fa-solid fa-circle-info"></i> ${escapeHtml(line)}</div>`;
        } else {
            html += `<div class="qa-line">${escapeHtml(line)}</div>`;
        }
    });

    return html;
}


function escapeHtml(str) {
    if (!str) return "";
    return String(str)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}
